340		existingCR, err := s.getControllerRevision(namespace, revisionName)
341		if err != nil {
342			return "", err
343		}
344	
345		snapshotCR := existingCR.DeepCopy()
346		snapshotCR.ObjectMeta.Reset()
347		snapshotCR.ObjectMeta.SetLabels(existingCR.Labels)
348	
349		// We strip out the source VM name from the CR name and replace it with the snapshot name
350		snapshotCR.Name = strings.Replace(existingCR.Name, s.snapshot.Spec.Source.Name, s.snapshot.Name, 1)
351	
352		// Ensure GVK is set before we attempt to create the controller OwnerReference below
353		obj, err := utils.GenerateKubeVirtGroupVersionKind(s.snapshot)
354		if err != nil {
355			return "", err
356		}
357		snapshot, ok := obj.(*snapshotv1.VirtualMachineSnapshot)
358		if !ok {
359			return "", fmt.Errorf("Unexpected object format returned from GenerateKubeVirtGroupVersionKind")
360		}
361		snapshotCR.OwnerReferences = []metav1.OwnerReference{*metav1.NewControllerRef(snapshot, snapshot.GroupVersionKind())}
362	
363		snapshotCR, err = s.controller.Client.AppsV1().ControllerRevisions(s.snapshot.Namespace).Create(context.Background(), snapshotCR, metav1.CreateOptions{})
364		if err != nil && !k8serrors.IsAlreadyExists(err) {
365			return "", err
366		}
367	
368		return snapshotCR.Name, nil
369	}
