// provided annotations map with the generation formatted as a decimal string.
func setGenerationAnnotation(generation int64, annotations map[string]string) {
	annotations[virtv1.VirtualMachineGenerationAnnotation] = strconv.FormatInt(generation, 10)
}

// setGenerationAnnotationOnVmi sets the VirtualMachineGenerationAnnotation on
// the VMI with the generation formatted as a decimal string. It merges the
// annotation into any existing annotations without removing them, initializing
// the annotations map if it is nil.
func setGenerationAnnotationOnVmi(generation int64, vmi *virtv1.VirtualMachineInstance) {
	annotations := vmi.GetAnnotations()
	if annotations == nil {
		annotations = map[string]string{}
	}

	setGenerationAnnotation(generation, annotations)
	vmi.SetAnnotations(annotations)
}

// getGenerationAnnotation returns a pointer to the string value of the
// VirtualMachineGenerationAnnotation on the VMI if it exists. If the annotation
// is not present, or the annotations map is empty, (nil, nil) is returned.
func getGenerationAnnotation(vmi *virtv1.VirtualMachineInstance) (*string, error) {
	if vmi == nil {
		return nil, errors.New("passed nil pointer")
	}

	annotations := vmi.GetAnnotations()
	if len(annotations) == 0 {
		return nil, nil
	}

	generationStr, exists := annotations[virtv1.VirtualMachineGenerationAnnotation]
	if !exists {
		return nil, nil
	}

	return &generationStr, nil
}

// patchVmGenerationAnnotationOnVmi patches the VMI in the Kubernetes API to set
// the VirtualMachineGenerationAnnotation to the given generation formatted as a
// decimal string.
func (c *Controller) patchVmGenerationAnnotationOnVmi(generation int64, vmi *virtv1.VirtualMachineInstance) (*virtv1.VirtualMachineInstance, error) {
	newAnnotations := maps.Clone(vmi.Annotations)
	if newAnnotations == nil {
		newAnnotations = map[string]string{}
	}
	setGenerationAnnotation(generation, newAnnotations)

	patchSet := patch.New()
	if vmi.Annotations == nil {
		patchSet.AddOption(patch.WithAdd("/metadata/annotations", newAnnotations))
	} else {
		patchSet.AddOption(
			patch.WithTest("/metadata/annotations", vmi.Annotations),
			patch.WithReplace("/metadata/annotations", newAnnotations),
		)
	}

	generatedPatch, err := patchSet.GeneratePayload()
	if err != nil {
		return vmi, err
	}

	patchedVMI, err := c.clientset.VirtualMachineInstance(vmi.Namespace).Patch(context.Background(), vmi.Name, types.JSONPatchType, generatedPatch, metav1.PatchOptions{})
	if err != nil {
		return vmi, err
	}

	return patchedVMI, nil
}

// conditionallyBumpGenerationAnnotationOnVmi will bump the generation annotation
// on the VMI to vm.Generation, but only when the generation differs from the
// current annotation value and the VM's template spec is identical to the
// template spec stored in the controller revision (retrieved from the
// Kubernetes API by name). This allows the generation annotation to track
// live-updatable changes (which do not restart the VMI), while avoiding bumping
// the annotation when a non-live-updatable change to the template spec was made
// (which requires a restart). Changes to non-template fields such as
// RunStrategy do not prevent the bump.
func (c *Controller) conditionallyBumpGenerationAnnotationOnVmi(vm *virtv1.VirtualMachine, vmi *virtv1.VirtualMachineInstance) (*virtv1.VirtualMachineInstance, error) {
	if vm == nil || vmi == nil {
		return vmi, nil
	}

	currentGenerationAnnotation, err := getGenerationAnnotation(vmi)
	if err != nil {
		return vmi, err
	}

	// If the annotation already matches the current generation there is nothing
	// to do. If the annotation is missing, proceed as if a bump is needed.
	if currentGenerationAnnotation != nil && *currentGenerationAnnotation == strconv.FormatInt(vm.Generation, 10) {
		return vmi, nil
	}

	cr, err := c.clientset.AppsV1().ControllerRevisions(vm.Namespace).Get(context.Background(), vmi.Status.VirtualMachineRevisionName, metav1.GetOptions{})
	if err != nil {
		return vmi, err
	}

	revisionData := VirtualMachineRevisionData{}
	if err = json.Unmarshal(cr.Data.Raw, &revisionData); err != nil {
		return vmi, err
	}

	// Only bump the annotation when the template spec has not changed. A change
	// to the template spec requires a restart, so the annotation should keep
	// lagging behind until the VMI is restarted.
	if !equality.Semantic.DeepEqual(revisionData.Spec.Template, vm.Spec.Template) {
		return vmi, nil
	}

	return c.patchVmGenerationAnnotationOnVmi(vm.Generation, vmi)
}

// syncGenerationInfo will update the vm.Status with the ObservedGeneration from
// the VMI generation annotation, and the DesiredGeneration from the vm current
// generation. When the annotation is missing or malformed, the generation is
// recovered from the controller revision and patched onto the VMI.
func (c *Controller) syncGenerationInfo(vm *virtv1.VirtualMachine, vmi *virtv1.VirtualMachineInstance, logger *log.FilteredLogger) (*virtv1.VirtualMachineInstance, error) {
	if vm == nil || vmi == nil {
		return vmi, errors.New("passed nil pointer")
	}

	generationStr, err := getGenerationAnnotation(vmi)
	if err != nil {
		return vmi, err
	}

	var generation *int64
	if generationStr != nil {
		if parsed, parseErr := strconv.ParseInt(*generationStr, 10, 64); parseErr == nil {
			generation = &parsed
		} else {
			logger.Reason(parseErr).Errorf("Failed to parse generation annotation %v as an int", *generationStr)
		}
	}

	if generation == nil {
		// The annotation is missing or malformed. Recover the generation from
		// the controller revision and patch it onto the VMI.
		cr, err := c.clientset.AppsV1().ControllerRevisions(vm.Namespace).Get(context.Background(), vmi.Status.VirtualMachineRevisionName, metav1.GetOptions{})
		if err != nil {
			return vmi, err
		}

		vmi, err = c.patchVmGenerationAnnotationOnVmi(cr.Revision, vmi)
		if err != nil {
			return vmi, err
		}

		vm.Status.ObservedGeneration = cr.Revision
		vm.Status.DesiredGeneration = cr.Revision
		return vmi, nil
	}

	vm.Status.ObservedGeneration = *generation
	vm.Status.DesiredGeneration = vm.Generation

	return vmi, nil
