func (c *VMController) syncGenerationInfo(vm *virtv1.VirtualMachine, vmi *virtv1.VirtualMachineInstance, logger *log.FilteredLogger) error {
	if vm == nil || vmi == nil {
		return errors.New("passed nil pointer")
	}

